"""Intent tests for risk.annualize (M1-T18, RISK-03, TC-06)."""

from __future__ import annotations

import dataclasses

import pytest

from risk import Returns, VolSeries, annualize


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={k: tuple(v) for k, v in payload["values"].items()},
    )


def _vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={k: tuple(v) for k, v in payload["values"].items()},
    )


def _assert_matches(result: VolSeries, expected: dict) -> None:
    tol = expected["tol"]
    assert set(result.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = result.values[ticker]
        assert len(got) == len(want), ticker
        for i, (g, w) in enumerate(zip(got, want, strict=True)):
            if w is None:
                assert g is None, f"{ticker}[{i}] gap not kept"
            else:
                assert g is not None, f"{ticker}[{i}] became a gap"
                assert g == pytest.approx(w, abs=tol), f"{ticker}[{i}]"


@pytest.mark.intent
def test_tc06_values_scaled_by_sqrt_252_gaps_kept(golden) -> None:
    inp, expected = golden("risk", "TC-06")
    vol = _vol(inp["vol"])
    result = annualize(vol)
    assert isinstance(result, VolSeries)
    assert result.annualized is expected["annualized"]
    _assert_matches(result, expected)


@pytest.mark.intent
def test_tc06_explicit_252_periods_matches_default(golden) -> None:
    inp, expected = golden("risk", "TC-06")
    result = annualize(_vol(inp["vol"]), periods_per_year=252)
    assert result.annualized is True
    _assert_matches(result, expected)


@pytest.mark.intent
def test_tc06_returns_and_window_carried_through(golden) -> None:
    inp, _ = golden("risk", "TC-06")
    vol = _vol(inp["vol"])
    result = annualize(vol)
    assert result.returns == vol.returns
    assert result.window == vol.window


@pytest.mark.intent
def test_tc06_input_not_mutated(golden) -> None:
    inp, _ = golden("risk", "TC-06")
    vol = _vol(inp["vol"])
    before = {k: tuple(v) for k, v in vol.values.items()}
    annualize(vol)
    assert vol.annualized is False
    assert {k: tuple(v) for k, v in vol.values.items()} == before


@pytest.mark.intent
def test_annualizing_annualized_sample_is_value_error(contract_sample) -> None:
    vol = _vol(contract_sample("risk.VolSeries"))
    assert vol.annualized is True
    with pytest.raises(ValueError, match=r"(?i)annuali"):
        annualize(vol)


@pytest.mark.intent
def test_annualizing_twice_is_value_error(golden) -> None:
    inp, _ = golden("risk", "TC-06")
    daily = _vol(inp["vol"])
    already = dataclasses.replace(daily, annualized=True)
    with pytest.raises(ValueError, match=r"(?i)annuali"):
        annualize(already)

